-- The two checklists published on 2026-10-21: Cutting Back on Drinking
-- (Drinking) and Visiting Someone in the Hospital (Visiting).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-21`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('cutting-back-on-drinking', 'Cutting Back on Drinking', 'For the weeks you want to drink less without making it a whole identity. It gets the real number written down, names the nights that stay dry, puts a sentence in your pocket for the offer, and treats a slip as information.', 'Drinking', '["Write down what you actually drank this week — the real number is usually a surprise.", "Pick the nights that stay dry, by name — Tuesday and Thursday beats “fewer nights”.", "Decide the number before you go out — in the moment is the worst time to choose it.", "Have the first one later than usual — the clock moves the total more than willpower does.", "Keep something you like that is not alcohol — a glass in your hand answers most of the questions.", "Have one sentence ready for the offer — “not tonight, thanks” needs nothing added after it.", "Notice which situation does most of it — a person, a time of day, a feeling you are leaving.", "Count a slip as data, not a verdict — the week is not spoiled and you are not back at zero.", "Tell your doctor if you drink every day — stopping suddenly is not always safe to do alone."]'::jsonb, 'weekly', array['Habits', 'Self-Compassion']::text[], 1, '2026-10-21T16:00:00+00:00'::timestamptz),
  ('visiting-someone-in-the-hospital', 'Visiting Someone in the Hospital', 'For going to see someone in the hospital when you are not sure what helps. It keeps the visit short, puts something useful in your bag, lets them choose the subject, and leaves one concrete offer behind on the way out.', 'Visiting', '["Ask before you go rather than surprise them — some days a visit is the last thing wanted.", "Plan for twenty minutes, not an afternoon — short and soon beats long and only once.", "Bring something small and useful — lip balm, a phone charger, a decent pair of socks.", "Sit down at their eye level — standing over a bed makes a visit feel like an inspection.", "Let them steer what gets talked about — the weather and the gossip are allowed to win.", "Skip the stories about someone else''s case — nobody in a bed needs the comparison.", "Ask the nurse what helps, not the internet — they know what this ward actually allows.", "Offer one concrete thing as you leave — the plants, the mail, a ride home on Thursday.", "Let yourself feel wrung out afterward — hospitals take something out of the visitors too."]'::jsonb, 'as needed', array['Caregiving', 'Communication']::text[], 1, '2026-10-21T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
